var o={name:"Nam Nguyen",headline:"Lead front-end developer",target:"Senior Software Engineer, Web Development",targetAlt:"Senior Front-End Engineer, Web",place:"Uppsala, Sweden",commute:"38 minutes from the Stockholm office. No relocation, no visa sponsorship needed.",emailUser:"hainam2511",emailHost:"gmail.com",links:[{label:"GitHub",handle:"southocean",href:"https://github.com/southocean"},{label:"LinkedIn",handle:"southocean",href:"https://www.linkedin.com/in/southocean"},{label:"itch.io",handle:"southocean",href:"https://southocean.itch.io"}],languages:"Vietnamese (native) \xB7 English C2 \xB7 Swedish C1"},s="2026-08-20",l="https://southocean.github.io/callback/",h="Seven years leading the front end of a real-time multiplayer client: shared state, reconnection, latency, a rendering engine embedded in a web app. The same shape of problem as a video call.",c=[{id:"mahjong",org:"Wasabi Productions",title:"Lead front-end developer",from:2019.25,to:null,fromLabel:"Apr 2019",toLabel:"present",place:"Uppsala, Sweden",kind:"engineering",gist:"Seven years on a real-time multiplayer game client. The closest thing on this CV to a video call.",bullets:["Game client for online mahjong, built for the Chinese and Japanese markets.","Took the product through every platform it has had: web, then Unity, now React Native on web and mobile.","Pioneered agentic programming: built the cross-team AI harnesses, drove adoption beyond my team.","Feature design, responsive UI, advanced Mahjong bot (4\u20135 Dan), bot swarm controller, automated QA.","Worked directly with design, backend, marketing and investors, with an active say in what gets built next."]},{id:"research",org:"D&A Research",title:"Data and algorithms research",from:2014,to:2018.85,fromLabel:"2014",toLabel:"2018",place:"Uppsala \xB7 Hanoi",kind:"research",gist:"Graph mining and combinatorial optimisation. This is where the algorithms came from.",bullets:["Graph mining for the Multinet open-source library. InfoLab, Uppsala University, 2018.","Sensor network optimisation: two papers, a book chapter, a best-paper award. MSO Lab, HUST, 2014\u20132017."]},{id:"bkav",org:"Bkav Corp.",title:"C++ developer",from:2013.7,to:2015.85,fromLabel:"Sep 2013",toLabel:"Nov 2015",place:"Hanoi, Vietnam",kind:"engineering",gist:"Security tokens in C++. Where getting it exactly right was the whole job.",bullets:["Built eToken, a hardware security token for signing and verifying digital signatures.","Delivered a beta meeting the relevant ISO standards."]}],d=[{id:"mahjong",title:"A real-time multiplayer client, through two platform migrations",org:"Wasabi Productions",years:"2019\u2013present",stack:["JavaScript","React","Unity","C#","REST APIs","responsive UI"],problem:"Four players at a table, in different countries, on different networks, all of whom must see the same board at the same moment. One of them is on hotel wifi. The client has to stay honest about shared state while the connection underneath it is not honest at all.",approach:["Took the product from a native desktop app to the browser, then to a hybrid running React for interface and Unity for the table itself: a rendering engine inside a web app, kept in step.","Designed the API surface between client and server, which is where the reconnection and resync behaviour actually lives.","Built a bot controller so live tables could be driven under test instead of by hand. Test automation for a system whose hardest bugs only appear with four real participants.","Localised for the Chinese and Japanese markets, where the game conventions and the typography both differ.","Led five engineers: split the work, ran the reviews, and defended the architecture to designers, marketing and investors."],relevance:"A conferencing client is this problem with media attached. Shared session state, participants joining and dropping, a resync that must not lose the room, and a rendering surface inside a web app that cannot be allowed to drop frames. I have been shipping that for seven years, in a browser."},{id:"callback",title:"This site",org:"Callback",years:"2026",stack:["TypeScript","WebGL","Web Audio","zero dependencies"],problem:"The Meet roles ask for TypeScript, test automation and accessible technologies. Claiming all three on a PDF is free, so a claim is worth nothing. The artifact had to be the evidence.",approach:["Strict TypeScript, no framework, no runtime dependencies. The whole bundle is under the budget printed in the footer, and the build fails if it goes over.","A real unit-test suite over real logic: the state reducer, timeline geometry, the caption scheduler, the network model. It runs in CI and in your browser, in the Engineering panel.","A chaos switch in that panel injects a fault so you can watch the suite go red. A green screenshot proves nothing.","A WebGL filter chain over live video, because effects are a feature this product ships and building one is more convincing than mentioning one.","A network simulator that degrades the call: loss, jitter, resolution collapse. The failure mode this team actually lives in.","Accessibility done as work rather than as a bullet: roving tabindex, focus traps, reduced-motion, and an audit panel that asserts against the live DOM and is allowed to fail.","Built with agentic tooling and the build log left in, since the senior posting asks for exactly that."],relevance:"Every requirement in the job ad has something here you can click on. That was the entire design brief."},{id:"etoken",title:"eToken: signing hardware, in C++",org:"Bkav Corp.",years:"2013\u20132015",stack:["C++","cryptographic signing","ISO conformance"],problem:'A device that signs documents has no acceptable margin of error and no useful way to say "roughly".',approach:["Researched and implemented the token that signs and verifies digital signatures.","Drove it to a beta meeting the relevant ISO standards, with conformance as the definition of done rather than a phase at the end."],relevance:"Two years in a codebase where correctness was the product. It is the reason I write tests before I am asked to."},{id:"research",title:"Combinatorial optimisation, published",org:"MSO Lab, HUST \xB7 InfoLab, Uppsala",years:"2014\u20132018",stack:["algorithms","genetic algorithms","graph mining","Matlab","Python"],problem:"Where to place sensors, how to route between them, and how to find a good answer when the exact one is out of reach.",approach:["Three years of wireless sensor network optimisation at MSO Lab. Two publications, a book chapter, and a best-paper award at IEEE R10-HTC.","Grant co-holder for IEEE AIYEHUM 2016 and 2017 and IEEE R-10 HTA 2017.","Master's thesis on graph mining over Twitter, contributed to the Multinet open-source library.","Taught the algorithms too: teaching assistant for Genetic Algorithms, Database Design and Advanced Software Design."],relevance:"Both postings list data structures and algorithms as preferred. This is not a weekend of practice problems. It is four years of it, peer-reviewed, and three semesters of teaching it to other people."}],p={primary:[{name:"Agentic programming",note:"cross-team AI harnesses at Wasabi, and this site: one person, one agent, one week"},{name:"Test automation",note:"75\u201390% unit coverage, AI-assisted, plus automated QA over the core flows"},{name:"Real-time clients",note:"shared state, reconnection and latency on a live multiplayer game"},{name:"Responsive & accessible UI",note:"roving tabindex, live regions, reduced motion, keyboard-only paths"},{name:"Performance",note:"load budget enforced in CI, asset optimisation, lazy loading"}],volume:{"Over 10,000 lines":["TypeScript","JavaScript","C","C++","C#","Dart","Java"],"Over 1,000 lines":["Erlang","SQL","Python","Matlab","R","PHP"],"Tools & frameworks":["React","Unity","Flutter","Figma"]}},g=[{school:"Uppsala University",award:"MSc, Computer Science",years:"2016\u20132018",place:"Uppsala, Sweden"},{school:"Tokyo University of Agriculture and Technology",award:"Research exchange",years:"2015",place:"Tokyo, Japan"},{school:"Hanoi University of Science and Technology",award:"BS, Computer Science",years:"2011\u20132016",place:"Hanoi, Vietnam"}],m=["Database Design (HT16, HT17)","Advanced Software Design (HT17)","Genetic Algorithms (2015)"],u={items:[{what:"Stand-up comedy",why:"Fyris Komedi and Comedy Nation. Competed in Uppsalas Roligaste 2026."},{what:"Acting",why:"Short films: Tomma H\xE4nder (.MOV Filmfestival 2026), The Darkest Hour, Don\u2019t Cry Over Spilled Milk."},{what:"Uppsala Zombie Walk organiser",why:"Website, marketing, makeup and logistics. Featured on SVT and UNT.",links:[{text:"SVT",href:"https://www.svt.se/nyheter/lokalt/uppsala/zombie-walk-i-uppsala"},{text:"UNT",href:"https://www.unt.se/kultur/hogtider/artikel/har-intar-zombierna-stan-se-spoklika-vandringen-/reo9w2yl"}]}]};function f(r,i=[]){let t=[],e=r;for(let a of i){let n=e.indexOf(a.text);n<0||(n>0&&t.push({text:e.slice(0,n)}),t.push({text:a.text,href:a.href}),e=e.slice(n+a.text.length))}return e&&t.push({text:e}),t}var b=[{req:"Bachelor's degree or equivalent",evidence:"BS Computer Science, HUST. MSc Computer Science, Uppsala.",strength:"strong"},{req:"5 years software development",evidence:"Bkav 2013\u20132015, Wasabi Productions 2019\u2013present. Twelve years since the first professional line.",strength:"strong"},{req:"3 years front-end and UI development",evidence:"Seven years leading front end at Wasabi Productions, including all UX and responsive work.",strength:"strong"},{req:"3 years testing, maintaining or launching software",evidence:"Two platform launches on the same product, plus a bot controller built to test live tables.",strength:"strong"},{req:"1 year software design and architecture",evidence:"Owned the desktop \u2192 web \u2192 React + Unity hybrid re-architecture, and the client/server API surface.",strength:"strong"},{req:"Preferred: Master's or PhD",evidence:"MSc, Uppsala University, 2018.",strength:"strong"},{req:"Preferred: 5 years data structures and algorithms",evidence:"Four years optimisation research, two publications, a book chapter, a best-paper award, three semesters as an algorithms TA.",strength:"strong"},{req:"Preferred: technical leadership",evidence:"Led a team of five for seven years: task breakdown, reviews, architecture decisions.",strength:"strong"},{req:"Preferred: accessible technologies",evidence:"No shipped product where it was my mandate. So the evidence is this build: keyboard-complete, screen-reader tested, with a live audit in the Engineering panel that is allowed to fail.",strength:"honest"},{req:"TypeScript (required for SWE III)",evidence:"This site: strict TypeScript, no framework, no runtime dependencies, size-gated in CI.",strength:"met"},{req:"Agentic coding techniques and tools",evidence:"Built with them, and the build log is in the Engineering panel: reviews, objections, what changed.",strength:"met"}],w="Nam Nguyen, Uppsala. Seven years as lead front-end developer. Always very extra in all the right ways. His CV is a proof of that, an homage to Google Meet: ",v={siteName:"Callback",why:["A phone callback: what I am asking for.","A JS callback: what the job is.","A stand-up callback: a joke that refers back to an earlier joke."]};export{o as a,s as b,l as c,h as d,c as e,d as f,p as g,g as h,m as i,u as j,f as k,b as l,w as m,v as n};
